129 |     <script>
130 |       const CELL = 12, SIZE = 64;
131 |       const board     = document.getElementById("board");
132 |       const overlay   = document.getElementById("overlay");
133 |       const selOverlay = document.getElementById("selection-overlay");
134 |       const btnTable  = document.getElementById("btn-table");
135 |       const btnEdit   = document.getElementById("btn-edit");
136 |       const btnDelete = document.getElementById("btn-delete");
137 |       const boardWrap = document.getElementById("board-wrap");
138 | 
139 |       const TABLE_COLORS = [
140 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
141 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
142 |       ];
143 | 
144 |       // ── State ────────────────────────────────────────────────────────────────
145 |       let tableCount = 0;
146 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
147 |       const tableGrid = [];   // tableGrid[row][col] = table id or null
148 |       let selectedTable = null;   // table currently clicked/focused
149 |       let editingTable  = null;   // table lifted into edit mode
150 | 
151 |       // ── Build cell grid ──────────────────────────────────────────────────────
152 |       const cells = [];
153 |       for (let row = 0; row < SIZE; row++) {
154 |         cells[row] = []; tableGrid[row] = [];
155 |         for (let col = 0; col < SIZE; col++) {
156 |           const cell = document.createElement("div");
157 |           cell.classList.add("cell");
158 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
159 |           cell.dataset.row = row; cell.dataset.col = col;
160 |           cells[row][col] = cell; tableGrid[row][col] = null;
161 |           board.appendChild(cell);
162 |         }
163 |       }
164 | 
165 |       // ── Selection helpers ────────────────────────────────────────────────────
166 |       let selection = null;
167 |       let isSelecting = false, selStartRow = null, selStartCol = null;
168 | 
169 |       function clearClass(cls) {
170 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
171 |       }
172 |       function paintRect(r1,c1,r2,c2,cls) {
173 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
174 |       }
175 |       function renderSelection() {
176 |         clearClass("selected");
177 |         if (selection) {
178 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
179 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
180 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
181 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
182 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
183 |           selOverlay.style.display = "block";
184 |         } else {
185 |           selOverlay.style.display = "none";
186 |         }
187 |         btnTable.disabled = !selection;
188 |         btnEdit.disabled  = !selectedTable;
189 |       }
190 |       function selPreviewRect(curRow,curCol) {
191 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
192 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
193 |         if (!selection) return {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
194 |         return {
195 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
196 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
197 |         };
198 |       }
199 |       function applySelPreview(curRow,curCol) {
200 |         clearClass("preview");

200 |         clearClass("preview");
201 |         clearClass("conflict");
202 |         const r = selPreviewRect(curRow,curCol);
203 |         for (let row=r.rMin;row<=r.rMax;row++) {
204 |           for (let col=r.cMin;col<=r.cMax;col++) {
205 |             if (tableGrid[row][col] !== null) {
206 |               cells[row][col].classList.add("conflict");
207 |             } else {
208 |               cells[row][col].classList.add("preview");
209 |             }
210 |           }
211 |         }
212 |         // Keep dotted selection outline tracking the live preview rect
213 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
214 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
215 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
216 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
217 |         selOverlay.style.display = "block";
218 |       }
219 | 
220 | 
221 |       // ── Cell colour helpers ──────────────────────────────────────────────────
222 |       function resetCell(r,c) {
223 |         const cell = cells[r][c];
224 |         cell.style.backgroundColor = "";
225 |         cell.style.opacity = "";
226 |         cell.classList.remove("selected","preview");
227 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
228 |         tableGrid[r][c] = null;
229 |       }
230 |       function stampTable(t) {
231 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
232 |           const cell = cells[r][c];
233 |           cell.classList.remove("selected","light","dark","preview");
234 |           cell.style.backgroundColor = t.color;
235 |           cell.style.opacity = "0.85";
236 |           tableGrid[r][c] = t.id;
237 |         }
238 |       }
239 |       function eraseTable(t) {
240 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) resetCell(r,c);
241 |       }
242 |       function positionEl(t) {
243 |         t.el.style.left   = (t.cMin * CELL) + "px";
244 |         t.el.style.top    = (t.rMin * CELL) + "px";
245 |         t.el.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
246 |         t.el.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
247 |       }
248 | 
249 |       // ── Table selection & edit ───────────────────────────────────────────────
250 |       function updateToolbar() {
251 |         btnTable.disabled  = !selection;
252 |         btnEdit.disabled   = !selectedTable;
253 |         btnDelete.disabled = !selectedTable;
254 |       }
255 | 
256 |       function selectTable(t) {
257 |         if (selectedTable) selectedTable.el.classList.remove("table-selected");
258 |         selectedTable = t;
259 |         if (t) t.el.classList.add("table-selected");
260 |         updateToolbar();
261 |       }
262 | 
263 |       function editTable(t) {
264 |         if (!t) return;
265 |         // Save original bounds in case user cancels
266 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
267 |         editingTable = t;
268 |         // Lift the table off the board into the active selection
269 |         eraseTable(t);
270 |         t.el.style.display = "none";
271 |         // Load its area as the current selection
272 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
273 |         renderSelection();
274 |         selectTable(null);
275 |       }
276 | 
277 |       function cancelEdit() {
278 |         if (!editingTable) return;
279 |         const t = editingTable;
280 |         // Restore original position
281 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
282 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
283 |         delete t._editBackup;
284 |         stampTable(t);
285 |         positionEl(t);
286 |         t.el.style.display = "";
287 |         editingTable = null;
288 |         // Clear selection
289 |         selection = null;
290 |         clearClass("preview"); clearClass("conflict");
291 |         renderSelection();
292 |       }
293 | 
294 |       function deleteTable(t) {
295 |         if (!t) return;
296 |         // If this table is currently being edited, cancel the edit first
297 |         if (editingTable === t) {
298 |           editingTable = null;
299 |           delete t._editBackup;
300 |           selection = null;
301 |           clearClass("preview"); clearClass("conflict");
302 |         } else {
303 |           eraseTable(t);
304 |         }
305 |         // Remove overlay element
306 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
307 |         // Remove from tables array
308 |         const idx = tables.indexOf(t);
309 |         if (idx !== -1) tables.splice(idx, 1);
310 |         // Deselect
311 |         if (selectedTable === t) selectTable(null);
312 |         renderSelection();
313 |       }
314 | 
315 |       // ── Conflict detection ───────────────────────────────────────────────────
316 |       // Returns true if the given rect overlaps any table cell (optionally ignoring one table id)
317 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
318 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
319 |           const tid = tableGrid[r][c];
320 |           if (tid !== null && tid !== ignoreId) return true;
321 |         }
322 |         return false;
323 |       }
324 | 
325 |       // ── Place Table ──────────────────────────────────────────────────────────
326 |       function placeTable() {
327 |         if (!selection) return;
328 |         const { rMin, cMin, rMax, cMax } = selection;
329 |         const ignoreId = editingTable ? editingTable.id : null;
330 | 
331 |         if (hasConflict(rMin,cMin,rMax,cMax,ignoreId)) {
332 |           btnTable.classList.add("conflict");
333 |           setTimeout(() => btnTable.classList.remove("conflict"), 600);
334 |           return;
335 |         }
336 | 
337 |         if (editingTable) {
338 |           // Re-place the edited table with its new bounds
339 |           const t = editingTable;
340 |           editingTable = null;
341 |           delete t._editBackup;
342 |           t.rMin=rMin; t.cMin=cMin; t.rMax=rMax; t.cMax=cMax;
343 |           stampTable(t);
344 |           positionEl(t);
345 |           t.el.style.display = "";
346 |           selection = null;
347 |           renderSelection();
348 |           return;
349 |         }
350 | 
351 |         const color = TABLE_COLORS[tableCount % TABLE_COLORS.length];
352 |         const id    = tableCount++;
353 |         const label = `Table ${id + 1}`;
354 | 
355 |         const el = document.createElement("div");
356 |         el.className = "table-rect";
357 |         el.style.backgroundColor = color + "44";
358 |         el.style.borderColor = color;
359 |         el.textContent = label;
360 | 
361 |         const t = { id, rMin, cMin, rMax, cMax, color, label, el };
362 |         tables.push(t);
363 |         positionEl(t);
364 |         stampTable(t);
365 |         overlay.appendChild(el);
366 |         el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
367 |         el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
368 | 
369 |         selection = null;
370 |         renderSelection();
371 |       }
372 | 
373 |       btnTable.addEventListener("click", placeTable);
374 |       btnEdit.addEventListener("click", () => editTable(selectedTable));
375 |       btnDelete.addEventListener("click", () => deleteTable(selectedTable));
376 |       document.addEventListener("keydown", (e) => {
377 |         if (e.key==="t"||e.key==="T")      placeTable();
378 |         if (e.key==="e"||e.key==="E")      editTable(selectedTable);
379 |         if (e.key==="d"||e.key==="D")      deleteTable(selectedTable);
380 |         if (e.key==="Escape")              cancelEdit();
381 |       });
382 | 
383 | 
384 |       // ── Table drag ───────────────────────────────────────────────────────────
385 |       let movingTable = null, moveOffsetRow = 0, moveOffsetCol = 0, ghost = null;
386 | 
387 |       function clearDragConflict() { clearClass("conflict"); }
388 | 
389 |       function applyDragConflict(rMin,cMin,rMax,cMax,ignoreId) {
390 |         clearDragConflict();
391 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
392 |           const tid = tableGrid[r][c];
393 |           if (tid !== null && tid !== ignoreId) cells[r][c].classList.add("conflict");
394 |         }
395 |       }
396 | 
397 |       function boardCoords(e) {
398 |         const rect = boardWrap.getBoundingClientRect();
399 |         return {
400 |           row: Math.floor((e.clientY - rect.top)  / CELL),

400 |           row: Math.floor((e.clientY - rect.top)  / CELL),
401 |           col: Math.floor((e.clientX - rect.left) / CELL),
402 |         };
403 |       }
404 | 
405 |       function clampTable(rMin,cMin,rMax,cMax) {
406 |         let dr=0, dc=0;
407 |         if (rMin<0)    dr=-rMin;
408 |         if (cMin<0)    dc=-cMin;
409 |         if (rMax>=SIZE) dr=SIZE-1-rMax;
410 |         if (cMax>=SIZE) dc=SIZE-1-cMax;
411 |         return {rMin:rMin+dr, cMin:cMin+dc, rMax:rMax+dr, cMax:cMax+dc};
412 |       }
413 | 
414 |       function onTableMouseDown(e, t) {
415 |         e.preventDefault();
416 |         e.stopPropagation();
417 |         const {row,col} = boardCoords(e);
418 |         moveOffsetRow = row - t.rMin;
419 |         moveOffsetCol = col - t.cMin;
420 |         movingTable   = t;
421 |         let hasMoved  = false;
422 |         t.el.classList.add("moving");
423 | 
424 |         // ghost mirrors table size
425 |         ghost = document.createElement("div");
426 |         ghost.className = "table-ghost";
427 |         ghost.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
428 |         ghost.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
429 |         ghost.style.left   = t.el.style.left;
430 |         ghost.style.top    = t.el.style.top;
431 |         ghost.style.display = "none"; // hidden until mouse actually moves
432 |         overlay.appendChild(ghost);
433 | 
434 |         // We need a one-time mousemove to detect whether this is a drag
435 |         function onFirstMove() {
436 |           hasMoved = true;
437 |           ghost.style.display = "";
438 |           document.removeEventListener("mousemove", onFirstMove);
439 |         }
440 |         document.addEventListener("mousemove", onFirstMove);
441 | 
442 |         // One-time mouseup to resolve click vs drag
443 |         function onUp(upE) {
444 |           document.removeEventListener("mouseup", onUp, true);
445 |           document.removeEventListener("mousemove", onFirstMove);
446 |           t.el.classList.remove("moving");
447 |           overlay.removeChild(ghost);
448 |           ghost = null;
449 | 
450 |           if (!hasMoved) {
451 |             // It was a bare click — select this table, don't move it
452 |             movingTable = null;
453 |             selectTable(selectedTable === t ? null : t);
454 |             return;
455 |           }
456 | 
457 |           // It was a drag — commit the move (handled by the global mouseup below)
458 |           // We do nothing here; the global handler fires on the same event
459 |         }
460 |         document.addEventListener("mouseup", onUp, true);
461 |       }
462 | 
463 |       document.addEventListener("mousemove", (e) => {
464 |         if (!movingTable) return;
465 |         const {row,col} = boardCoords(e);
466 |         const h = movingTable.rMax - movingTable.rMin;
467 |         const w = movingTable.cMax - movingTable.cMin;
468 |         const s = clampTable(row-moveOffsetRow, col-moveOffsetCol,
469 |                              row-moveOffsetRow+h, col-moveOffsetCol+w);
470 |         ghost.style.left           = (s.cMin*CELL)+"px";
471 |         ghost.style.top            = (s.rMin*CELL)+"px";
472 |         movingTable.el.style.left  = (s.cMin*CELL)+"px";
473 |         movingTable.el.style.top   = (s.rMin*CELL)+"px";
474 |         // Tint ghost red if drop zone conflicts with another table
475 |         const conflict = hasConflict(s.rMin,s.cMin,s.rMax,s.cMax, movingTable.id);
476 |         ghost.style.borderColor      = conflict ? "rgba(255,80,80,0.9)" : "rgba(255,255,255,0.6)";
477 |         ghost.style.backgroundColor  = conflict ? "rgba(255,60,60,0.25)" : "rgba(255,255,255,0.12)";
478 |         // Highlight the specific conflicting cells red
479 |         if (conflict) applyDragConflict(s.rMin,s.cMin,s.rMax,s.cMax, movingTable.id);
480 |         else clearDragConflict();
481 |       });
482 | 
483 |       document.addEventListener("mouseup", (e) => {
484 |         if (!movingTable) return;
485 |         const t = movingTable;
486 |         const {row,col} = boardCoords(e);
487 |         const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
488 |         const s = clampTable(row-moveOffsetRow, col-moveOffsetCol,
489 |                              row-moveOffsetRow+h, col-moveOffsetCol+w);
490 | 
491 |         const conflict = hasConflict(s.rMin,s.cMin,s.rMax,s.cMax, t.id);
492 | 
493 |         clearDragConflict();
494 |         eraseTable(t);
495 |         if (!conflict) {
496 |           t.rMin=s.rMin; t.cMin=s.cMin; t.rMax=s.rMax; t.cMax=s.cMax;
497 |         }
498 |         // If conflict, t's coords are unchanged → snap back to original position
499 |         stampTable(t);
500 |         positionEl(t);
501 |         t.el.classList.remove("moving");
502 |         overlay.removeChild(ghost);
503 |         ghost = null; movingTable = null;
504 |       });
505 | 
506 |       // ── Board selection mouse events ─────────────────────────────────────────
507 |       board.addEventListener("dragstart", (e) => e.preventDefault());
508 | 
509 |       board.addEventListener("mousedown", (e) => {
510 |         if (movingTable) return;
511 |         e.preventDefault();
512 |         const cell = e.target.closest(".cell");
513 |         if (!cell) return;
514 |         const row=parseInt(cell.dataset.row), col=parseInt(cell.dataset.col);
515 |         if (tableGrid[row][col] !== null) return;
516 |         // Clicking blank board deselects any selected table
517 |         selectTable(null);
518 |         isSelecting=true; selStartRow=row; selStartCol=col;
