btnTable.addEventListener("click", placeTable);
btnEdit.addEventListener("click", () => editTable(selectedTable));
btnDelete.addEventListener("click", () => deleteTable(selectedTable));
document.addEventListener("keydown", (e) => {
  if (e.key==="t"||e.key==="T")      placeTable();
  if (e.key==="e"||e.key==="E")      editTable(selectedTable);
  if (e.key==="d"||e.key==="D")      deleteTable(selectedTable);
  if (e.key==="Escape")              { cancelEdit(); exitCouchMode(); }
  if (e.key==="c"||e.key==="C")      toggleCouchMode();
});


// ── Couch mode ───────────────────────────────────────────────────────────
// A couch is always 1 row × 2 cols (minimum 1×2, restricted to 1×n).
const COUCH_ROWS = 1, COUCH_COLS = 2;
const COUCH_COLORS = [
  "#7b5ea7","#4a90d9","#2ecc71","#e67e22",
  "#1abc9c","#e74c3c","#9b59b6","#3498db",
];

function toggleCouchMode() {
  if (couchMode) exitCouchMode();
  else enterCouchMode();
}

function enterCouchMode() {
  couchMode = true;
  btnCouch.style.borderColor = "#b86fc4";
  btnCouch.style.background  = "#5a2d6a";
  board.style.cursor = "none";
}

function exitCouchMode() {
  if (!couchMode) return;
  couchMode = false;
  btnCouch.style.borderColor = "";
  btnCouch.style.background  = "";
  board.style.cursor = "crosshair";
  couchGhostEl.style.display = "none";
}

function updateCouchGhost(row, col) {
  // Clamp so the 1×2 ghost stays on board
  const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
  const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
  const rMax = rMin + COUCH_ROWS - 1;
  const cMax = cMin + COUCH_COLS - 1;
  couchGhostEl.style.left    = (cMin * CELL) + "px";
  couchGhostEl.style.top     = (rMin * CELL) + "px";
  couchGhostEl.style.width   = (COUCH_COLS * CELL) + "px";
  couchGhostEl.style.height  = (COUCH_ROWS * CELL) + "px";
  couchGhostEl.style.display = "block";
  const conflict = hasConflict(rMin, cMin, rMax, cMax);
  couchGhostEl.classList.toggle("conflict", conflict);
}

function placeCouch(row, col) {
  const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
  const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
  const rMax = rMin + COUCH_ROWS - 1;
  const cMax = cMin + COUCH_COLS - 1;
  if (hasConflict(rMin, cMin, rMax, cMax)) return; // can't place here

  const color = COUCH_COLORS[couchCount % COUCH_COLORS.length];
  const id    = tableCount++; // share global id counter so drag logic works uniformly
  couchCount++;
  const label = `Couch ${couchCount}`;

  const el = document.createElement("div");
  el.className = "couch-rect";
  el.style.backgroundColor = color + "55";
  el.style.borderColor = color;
  el.textContent = label;

  const t = { id, rMin, cMin, rMax, cMax, color, label, el, type: "couch" };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
  el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
}

// Follow cursor over the board in couch mode
board.addEventListener("mousemove", (e) => {
  if (!couchMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  updateCouchGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

// Hide ghost when leaving the board
board.addEventListener("mouseleave", () => {
  if (couchMode) couchGhostEl.style.display = "none";
});

// Click to place couch
board.addEventListener("click", (e) => {
  if (!couchMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  placeCouch(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

btnCouch.addEventListener("click", toggleCouchMode);

