  if (!hasMoved) {
    // It was a bare click — select this table, don't move it
    movingTable = null;
    selectTable(selectedTable === t ? null : t);
    return;
  }

  // It was a drag — commit the move (handled by the global mouseup below)
  // We do nothing here; the global handler fires on the same event
}
document.addEventListener("mouseup", onUp, true);

