// One-time mouseup to resolve click vs drag
function onUp(upE) {
  document.removeEventListener("mouseup", onUp, true);
  document.removeEventListener("mousemove", onFirstMove);

  if (!hasMoved) {
    // Bare click — clean up ghost and select, global handler is a no-op
    t.el.classList.remove("moving");
    overlay.removeChild(ghost);
    ghost = null;
    movingTable = null;
    selectTable(selectedTable === t ? null : t);
  }
  // If it was a real drag, leave ghost/movingTable for the global mouseup to commit & clean up
}
document.addEventListener("mouseup", onUp, true);

