275 |           const cell = cells[r][c];
276 |           cell.classList.remove("selected","light","dark","preview");
277 |           cell.style.backgroundColor = t.color;
278 |           cell.style.opacity = "0.85";
279 |           tableGrid[r][c] = t.id;
