292 |       // ── Table selection & edit ───────────────────────────────────────────────
293 |       function updateToolbar() {
294 |         btnTable.disabled  = !selection;
295 |         btnEdit.disabled   = !selectedTable;
296 |         btnDelete.disabled = !selectedTable;
297 |       }
