306 |       function editTable(t) {
307 |         if (!t) return;
308 |         // Save original bounds in case user cancels
309 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
310 |         editingTable = t;
311 |         // Lift the table off the board into the active selection
312 |         eraseTable(t);
313 |         t.el.style.display = "none";
314 |         // Load its area as the current selection
315 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
