320 |       function cancelEdit() {
321 |         if (!editingTable) return;
322 |         const t = editingTable;
323 |         // Restore original position
324 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
325 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
326 |         delete t._editBackup;
327 |         stampTable(t);
328 |         positionEl(t);
329 |         t.el.style.display = "";
330 |         editingTable = null;
331 |         // Clear selection
332 |         selection = null;
333 |         clearClass("preview"); clearClass("conflict");
334 |         renderSelection();
335 |       }
336 | 
337 |       function deleteTable(t) {
338 |         if (!t) return;
339 |         // If this table is currently being edited, cancel the edit first
340 |         if (editingTable === t) {
341 |           editingTable = null;
342 |           delete t._editBackup;
343 |           selection = null;
344 |           clearClass("preview"); clearClass("conflict");
345 |         } else {
346 |           eraseTable(t);
347 |         }
348 |         // Remove overlay element
349 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
350 |         // Remove from tables array
351 |         const idx = tables.indexOf(t);
352 |         if (idx !== -1) tables.splice(idx, 1);
