358 |       // ── Conflict detection ───────────────────────────────────────────────────
359 |       // Returns true if the given rect overlaps any table cell (optionally ignoring one table id)
360 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
361 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
362 |           const tid = tableGrid[r][c];
363 |           if (tid !== null && tid !== ignoreId) return true;
364 |         }
365 |         return false;
366 |       }
