368 |       // ── Place Table ──────────────────────────────────────────────────────────
369 |       function placeTable() {
370 |         if (!selection) return;
371 |         const { rMin, cMin, rMax, cMax } = selection;
372 |         const ignoreId = editingTable ? editingTable.id : null;
373 | 
374 |         if (hasConflict(rMin,cMin,rMax,cMax,ignoreId)) {
375 |           btnTable.classList.add("conflict");
376 |           setTimeout(() => btnTable.classList.remove("conflict"), 600);
377 |           return;
378 |         }
379 | 
380 |         if (editingTable) {
381 |           // Re-place the edited table with its new bounds
382 |           const t = editingTable;
383 |           editingTable = null;
384 |           delete t._editBackup;
385 |           t.rMin=rMin; t.cMin=cMin; t.rMax=rMax; t.cMax=cMax;
386 |           stampTable(t);
387 |           positionEl(t);
388 |           t.el.style.display = "";
389 |           selection = null;
390 |           renderSelection();
391 |           return;
392 |         }
393 | 
394 |         const color = TABLE_COLORS[tableCount % TABLE_COLORS.length];
395 |         const id    = tableCount++;
396 |         const label = `Table ${id + 1}`;
397 | 
398 |         const el = document.createElement("div");
399 |         el.className = "table-rect";
400 |         el.style.backgroundColor = color + "44";
401 |         el.style.borderColor = color;
402 |         el.textContent = label;
403 | 
404 |         const t = { id, rMin, cMin, rMax, cMax, color, label, el };
405 |         tables.push(t);
406 |         positionEl(t);
407 |         stampTable(t);
408 |         overlay.appendChild(el);
409 |         el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
410 |         el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
411 | 
412 |         selection = null;
413 |         renderSelection();
414 |       }
415 | 
416 |       btnTable.addEventListener("click", placeTable);
417 |       btnEdit.addEventListener("click", () => editTable(selectedTable));
418 |       btnDelete.addEventListener("click", () => deleteTable(selectedTable));
419 |       document.addEventListener("keydown", (e) => {
420 |         if (e.key==="t"||e.key==="T")      placeTable();
421 |         if (e.key==="e"||e.key==="E")      editTable(selectedTable);
422 |         if (e.key==="d"||e.key==="D")      deleteTable(selectedTable);
423 |         if (e.key==="Escape")              { cancelEdit(); exitCouchMode(); }
424 |         if (e.key==="c"||e.key==="C")      toggleCouchMode();
425 |       });
