428 |       // ── Couch mode ───────────────────────────────────────────────────────────
429 |       // A couch is always 1 row × 2 cols (minimum 1×2, restricted to 1×n).
430 |       const COUCH_ROWS = 1, COUCH_COLS = 2;
431 |       const COUCH_COLORS = [
432 |         "#7b5ea7","#4a90d9","#2ecc71","#e67e22",
433 |         "#1abc9c","#e74c3c","#9b59b6","#3498db",
434 |       ];
435 | 
436 |       function toggleCouchMode() {
437 |         if (couchMode) exitCouchMode();
438 |         else enterCouchMode();
439 |       }
440 | 
441 |       function enterCouchMode() {
442 |         couchMode = true;
443 |         btnCouch.style.borderColor = "#b86fc4";
444 |         btnCouch.style.background  = "#5a2d6a";
445 |         board.style.cursor = "none";
446 |       }
447 | 
448 |       function exitCouchMode() {
449 |         if (!couchMode) return;
450 |         couchMode = false;

450 |         couchMode = false;
451 |         btnCouch.style.borderColor = "";
452 |         btnCouch.style.background  = "";
453 |         board.style.cursor = "crosshair";
454 |         couchGhostEl.style.display = "none";
