457 |       function updateCouchGhost(row, col) {
458 |         // Clamp so the 1×2 ghost stays on board
459 |         const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
460 |         const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
461 |         const rMax = rMin + COUCH_ROWS - 1;
462 |         const cMax = cMin + COUCH_COLS - 1;
463 |         couchGhostEl.style.left    = (cMin * CELL) + "px";
464 |         couchGhostEl.style.top     = (rMin * CELL) + "px";
465 |         couchGhostEl.style.width   = (COUCH_COLS * CELL) + "px";
466 |         couchGhostEl.style.height  = (COUCH_ROWS * CELL) + "px";
467 |         couchGhostEl.style.display = "block";
468 |         const conflict = hasConflict(rMin, cMin, rMax, cMax);
469 |         couchGhostEl.classList.toggle("conflict", conflict);
470 |       }
471 | 
472 |       function placeCouch(row, col) {
473 |         const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
474 |         const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
475 |         const rMax = rMin + COUCH_ROWS - 1;
476 |         const cMax = cMin + COUCH_COLS - 1;
477 |         if (hasConflict(rMin, cMin, rMax, cMax)) return; // can't place here
478 | 
479 |         const color = COUCH_COLORS[couchCount % COUCH_COLORS.length];
480 |         const id    = tableCount++; // share global id counter so drag logic works uniformly
481 |         couchCount++;
482 |         const label = `Couch ${couchCount}`;
483 | 
484 |         const el = document.createElement("div");
485 |         el.className = "couch-rect";
486 |         el.style.backgroundColor = color + "55";
487 |         el.style.borderColor = color;
488 |         el.textContent = label;
489 | 
490 |         const t = { id, rMin, cMin, rMax, cMax, color, label, el, type: "couch" };
491 |         tables.push(t);
492 |         positionEl(t);
493 |         stampTable(t);
494 |         overlay.appendChild(el);
495 |         el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
496 |         el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
497 |       }
