510 |       });
511 | 
512 |       // Click to place couch
513 |       board.addEventListener("click", (e) => {
514 |         if (!couchMode) return;
515 |         const cell = e.target.closest(".cell");
516 |         if (!cell) return;
517 |         placeCouch(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
518 |       });
