523 |       // ── Table drag ───────────────────────────────────────────────────────────
524 |       let movingTable = null, moveOffsetRow = 0, moveOffsetCol = 0, ghost = null;
525 | 
526 |       function clearDragConflict() { clearClass("conflict"); }
527 | 
528 |       function applyDragConflict(rMin,cMin,rMax,cMax,ignoreId) {
529 |         clearDragConflict();
530 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
531 |           const tid = tableGrid[r][c];
532 |           if (tid !== null && tid !== ignoreId) cells[r][c].classList.add("conflict");
533 |         }
534 |       }
