536 |       function boardCoords(e) {
537 |         const rect = boardWrap.getBoundingClientRect();
538 |         return {
539 |           row: Math.floor((e.clientY - rect.top)  / CELL),
540 |           col: Math.floor((e.clientX - rect.left) / CELL),
541 |         };
542 |       }
543 | 
544 |       function clampTable(rMin,cMin,rMax,cMax) {
545 |         let dr=0, dc=0;
546 |         if (rMin<0)    dr=-rMin;
547 |         if (cMin<0)    dc=-cMin;
548 |         if (rMax>=SIZE) dr=SIZE-1-rMax;
549 |         if (cMax>=SIZE) dc=SIZE-1-cMax;
550 |         return {rMin:rMin+dr, cMin:cMin+dc, rMax:rMax+dr, cMax:cMax+dc};
551 |       }
552 | 
553 |       function onTableMouseDown(e, t) {
554 |         e.preventDefault();
555 |         e.stopPropagation();
556 |         const {row,col} = boardCoords(e);
557 |         moveOffsetRow = row - t.rMin;
558 |         moveOffsetCol = col - t.cMin;
559 |         movingTable   = t;
560 |         let hasMoved  = false;
561 |         t.el.classList.add("moving");
562 | 
563 |         // ghost mirrors table size
564 |         ghost = document.createElement("div");
565 |         ghost.className = "table-ghost";
566 |         ghost.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
567 |         ghost.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
568 |         ghost.style.left   = t.el.style.left;
569 |         ghost.style.top    = t.el.style.top;
570 |         ghost.style.display = "none"; // hidden until mouse actually moves
571 |         overlay.appendChild(ghost);
