575 |           hasMoved = true;
576 |           ghost.style.display = "";
577 |           document.removeEventListener("mousemove", onFirstMove);
578 |         }
579 |         document.addEventListener("mousemove", onFirstMove);
580 | 
581 |         // One-time mouseup to resolve click vs drag
582 |         function onUp(upE) {
583 |           document.removeEventListener("mouseup", onUp, true);
584 |           document.removeEventListener("mousemove", onFirstMove);
585 | 
586 |           if (!hasMoved) {
587 |             // Bare click — clean up ghost and select, global handler is a no-op
588 |             t.el.classList.remove("moving");
589 |             overlay.removeChild(ghost);
590 |             ghost = null;
591 |             movingTable = null;
592 |             selectTable(selectedTable === t ? null : t);
593 |           }
594 |           // If it was a real drag, leave ghost/movingTable for the global mouseup to commit & clean up
595 |         }
