/* Couch-placement / resize ghost — follows cursor when couch mode is active */
#couch-ghost {
  position: absolute;
  border: 2px dashed #b86fc4;
  background: rgba(184,111,196,0.25);
  border-radius: 3px;
  pointer-events: none;
  z-index: 9;
  display: none;
}
#couch-ghost.conflict {
  border-color: rgba(255,80,80,0.9);
  background: rgba(255,60,60,0.25);
}

/* Resize handles on left / right edges of a selected couch */
.couch-handle {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 16px;
  background: #b86fc4;
  border: 1px solid #fff6;
  border-radius: 3px;
  cursor: ew-resize;
  pointer-events: all;
  z-index: 11;
  opacity: 0;
  transition: opacity 0.15s;
}
.couch-handle.handle-left  { left:  -5px; }
.couch-handle.handle-right { right: -5px; }
.table-selected .couch-handle { opacity: 1; }

