function placeCouch(row, col) {
  const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
  const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
  const rMax = rMin + COUCH_ROWS - 1;
  const cMax = cMin + COUCH_COLS - 1;
  if (hasConflict(rMin, cMin, rMax, cMax)) return; // can't place here

  const color = COUCH_COLORS[couchCount % COUCH_COLORS.length];
  const id    = tableCount++; // share global id counter so drag logic works uniformly
  couchCount++;
  const label = `Couch ${couchCount}`;

  const el = document.createElement("div");
  el.className = "couch-rect";
  el.style.backgroundColor = color + "55";
  el.style.borderColor = color;

  const labelSpan = document.createElement("span");
  labelSpan.textContent = label;
  el.appendChild(labelSpan);

  // Resize handles (visible only when selected)
  const handleL = document.createElement("div");
  handleL.className = "couch-handle handle-left";
  const handleR = document.createElement("div");
  handleR.className = "couch-handle handle-right";
  el.appendChild(handleL);
  el.appendChild(handleR);

  const t = { id, rMin, cMin, rMax, cMax, color, label, el, type: "couch" };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => {
    // Don't start a body-drag when the user clicked a resize handle
    if (e.target.classList.contains("couch-handle")) return;
    onTableMouseDown(e, t);
  });
  el.addEventListener("click", (e) => { e.stopPropagation(); selectTable(t); });

  // Wire up resize handles
  handleL.addEventListener("mousedown", (e) => { e.stopPropagation(); startCouchResize(e, t, "left");  });
  handleR.addEventListener("mousedown", (e) => { e.stopPropagation(); startCouchResize(e, t, "right"); });
}

