448 |       // ── Couch mode ───────────────────────────────────────────────────────────
449 |       // A couch is always 1 row × 2 cols (minimum 1×2, restricted to 1×n).
450 |       const COUCH_ROWS = 1, COUCH_COLS = 2;

450 |       const COUCH_ROWS = 1, COUCH_COLS = 2;
451 |       const COUCH_COLORS = [
