477 |       function updateCouchGhost(row, col) {
478 |         // Clamp so the 1×2 ghost stays on board
479 |         const rMin = Math.max(0, Math.min(row, SIZE - COUCH_ROWS));
480 |         const cMin = Math.max(0, Math.min(col, SIZE - COUCH_COLS));
