// ── Chair mode ───────────────────────────────────────────────────────────
// A chair is always 1×1 — a single cell, rendered as a circle.
const CHAIR_COLOR = "#4ecdc4";

function toggleChairMode() {
  if (chairMode) exitChairMode();
  else enterChairMode();
}

function enterChairMode() {
  exitCouchMode();           // mutually exclusive
  chairMode = true;
  btnChair.style.borderColor = "#4ecdc4";
  btnChair.style.background  = "#1a5c58";
  board.style.cursor = "none";
}

function exitChairMode() {
  if (!chairMode) return;
  chairMode = false;
  btnChair.style.borderColor = "";
  btnChair.style.background  = "";
  board.style.cursor = "crosshair";
  chairGhostEl.style.display = "none";
}

function updateChairGhost(row, col) {
  chairGhostEl.style.left    = (col * CELL) + "px";
  chairGhostEl.style.top     = (row * CELL) + "px";
  chairGhostEl.style.width   = CELL + "px";
  chairGhostEl.style.height  = CELL + "px";
  chairGhostEl.style.display = "block";
  chairGhostEl.classList.toggle("conflict", hasConflict(row, col, row, col));
}

function placeChair(row, col) {
  if (hasConflict(row, col, row, col)) return;

  const id    = tableCount++;
  chairCount++;
  const label = `Ch${chairCount}`;

  const el = document.createElement("div");
  el.className = "chair-rect";
  el.style.backgroundColor = CHAIR_COLOR + "88";
  el.style.borderColor     = CHAIR_COLOR;
  el.textContent = label;

  const t = { id, rMin: row, cMin: col, rMax: row, cMax: col, color: CHAIR_COLOR, label, el, type: "chair" };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
  el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
}

// Follow cursor in chair mode
board.addEventListener("mousemove", (e) => {
  if (!chairMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  updateChairGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

board.addEventListener("mouseleave", () => {
  if (chairMode) chairGhostEl.style.display = "none";
});

// Click to place chair
board.addEventListener("click", (e) => {
  if (!chairMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  placeChair(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

btnChair.addEventListener("click", toggleChairMode);

