// ── Chair mode ───────────────────────────────────────────────────────────
// A chair is always 1×1 — a single cell, rendered as a circle.
// Chairs may only be placed (or dropped) in a cell orthogonally adjacent
// to at least one cell occupied by a piece of type "table".
const CHAIR_COLOR = "#4ecdc4";

// Returns true if (row,col) is orthogonally adjacent to a table cell.
function isAdjacentToTable(row, col) {
  const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
  for (const [dr, dc] of dirs) {
    const r = row + dr, c = col + dc;
    if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) continue;
    const id = tableGrid[r][c];
    if (id === null) continue;
    const piece = tables.find(t => t.id === id);
    if (piece && piece.type === "table") return true;
  }
  return false;
}

