function resetCell(r,c) {
  const cell = cells[r][c];
  cell.style.backgroundColor = "";
  cell.style.opacity = "";
  cell.classList.remove("selected","preview");
  cell.classList.add((r+c)%2===0 ? "light" : "dark");
  tableGrid[r][c] = [];
}
function stampTable(t) {
  for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
    const cell = cells[r][c];
    cell.classList.remove("selected","light","dark","preview");
    cell.style.backgroundColor = t.color;
    cell.style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}
function eraseTable(t) {
  for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) {
      resetCell(r, c);
    } else {
      // Repaint with the topmost remaining piece's colour
      const topId = tableGrid[r][c][tableGrid[r][c].length - 1];
      const top   = tables.find(p => p.id === topId);
      if (top) {
        cells[r][c].style.backgroundColor = top.color;
        cells[r][c].style.opacity = "0.85";
      }
    }
  }
}

