// ── Couch resize ─────────────────────────────────────────────────────────
// Handle "a" = left (h) or top (v); handle "b" = right (h) or bottom (v).
// Minimum extent is COUCH_COLS (2) cells in the active direction.

let resizingCouch = null; // { t, side }

function startCouchResize(e, t, side) {
  e.preventDefault();
  resizingCouch = { t, side };
  couchGhostEl.style.left    = (t.cMin * CELL) + "px";
  couchGhostEl.style.top     = (t.rMin * CELL) + "px";
  couchGhostEl.style.width   = ((t.cMax - t.cMin + 1) * CELL) + "px";
  couchGhostEl.style.height  = ((t.rMax - t.rMin + 1) * CELL) + "px";
  couchGhostEl.style.display = "block";
  couchGhostEl.classList.remove("conflict");
}

// Compute the proposed new bounds when dragging a resize handle.
function calcResizeBounds(t, side, rawRow, rawCol) {
  let rMin = t.rMin, rMax = t.rMax, cMin = t.cMin, cMax = t.cMax;
  if (t.orientation === "h") {
    const c = Math.max(0, Math.min(rawCol, SIZE - 1));
    if (side === "a") { // left handle — moves cMin
      cMin = Math.min(c, cMax - COUCH_COLS + 1);
      cMin = Math.max(0, cMin);
    } else {            // right handle — moves cMax
      cMax = Math.max(c, cMin + COUCH_COLS - 1);
      cMax = Math.min(SIZE - 1, cMax);
    }
  } else {
    const r = Math.max(0, Math.min(rawRow, SIZE - 1));
    if (side === "a") { // top handle — moves rMin
      rMin = Math.min(r, rMax - COUCH_COLS + 1);
      rMin = Math.max(0, rMin);
    } else {            // bottom handle — moves rMax
      rMax = Math.max(r, rMin + COUCH_COLS - 1);
      rMax = Math.min(SIZE - 1, rMax);
    }
  }
  return { rMin, rMax, cMin, cMax };
}

document.addEventListener("mousemove", (e) => {
  if (!resizingCouch) return;
  const { t, side } = resizingCouch;
  const { row, col } = boardCoords(e);
  const b = calcResizeBounds(t, side, row, col);
  const conflict = hasConflictForCouch(b.rMin, b.cMin, b.rMax, b.cMax, t.id);
  couchGhostEl.style.left   = (b.cMin * CELL) + "px";
  couchGhostEl.style.top    = (b.rMin * CELL) + "px";
  couchGhostEl.style.width  = ((b.cMax - b.cMin + 1) * CELL) + "px";
  couchGhostEl.style.height = ((b.rMax - b.rMin + 1) * CELL) + "px";
  couchGhostEl.classList.toggle("conflict", conflict);
});

document.addEventListener("mouseup", (e) => {
  if (!resizingCouch) return;
  const { t, side } = resizingCouch;
  resizingCouch = null;
  couchGhostEl.style.display = "none";
  const { row, col } = boardCoords(e);
  const b = calcResizeBounds(t, side, row, col);
  if (hasConflictForCouch(b.rMin, b.cMin, b.rMax, b.cMax, t.id)) return;
  eraseTable(t);
  t.rMin = b.rMin; t.rMax = b.rMax;
  t.cMin = b.cMin; t.cMax = b.cMax;
  stampTable(t);
  positionEl(t);
});

