function startCouchResize(e, t, side) {
  e.preventDefault();
  resizingCouch = { t, side, origCMin: t.cMin, origCMax: t.cMax };
  // Show resize ghost at current position
  couchGhostEl.style.left    = (t.cMin * CELL) + "px";
  couchGhostEl.style.top     = (t.rMin * CELL) + "px";
  couchGhostEl.style.width   = ((t.cMax - t.cMin + 1) * CELL) + "px";
  couchGhostEl.style.height  = (COUCH_ROWS * CELL) + "px";
  couchGhostEl.style.display = "block";
  couchGhostEl.classList.remove("conflict");
}

document.addEventListener("mousemove", (e) => {
  if (!resizingCouch) return;
  const { t, side } = resizingCouch;
  const { col } = boardCoords(e);
  const clampedCol = Math.max(0, Math.min(col, SIZE - 1));

  let newCMin = t.cMin, newCMax = t.cMax;
  if (side === "left") {
    // Left handle moves cMin; keep cMax fixed, enforce min width
    newCMin = Math.min(clampedCol, t.cMax - COUCH_COLS + 1);
    newCMin = Math.max(0, newCMin);
  } else {
    // Right handle moves cMax; keep cMin fixed, enforce min width
    newCMax = Math.max(clampedCol, t.cMin + COUCH_COLS - 1);
    newCMax = Math.min(SIZE - 1, newCMax);
  }

  const conflict = hasConflictForCouch(t.rMin, newCMin, t.rMax, newCMax, t.id);
  couchGhostEl.style.left  = (newCMin * CELL) + "px";
  couchGhostEl.style.width = ((newCMax - newCMin + 1) * CELL) + "px";
  couchGhostEl.classList.toggle("conflict", conflict);
});

document.addEventListener("mouseup", (e) => {
  if (!resizingCouch) return;
  const { t, side, origCMin, origCMax } = resizingCouch;
  resizingCouch = null;
  couchGhostEl.style.display = "none";

  const { col } = boardCoords(e);
  const clampedCol = Math.max(0, Math.min(col, SIZE - 1));

  let newCMin = t.cMin, newCMax = t.cMax;
  if (side === "left") {
    newCMin = Math.min(clampedCol, t.cMax - COUCH_COLS + 1);
    newCMin = Math.max(0, newCMin);
  } else {
    newCMax = Math.max(clampedCol, t.cMin + COUCH_COLS - 1);
    newCMax = Math.min(SIZE - 1, newCMax);
  }

  const conflict = hasConflictForCouch(t.rMin, newCMin, t.rMax, newCMax, t.id);
  if (conflict) {
    // Snap back — couch stays at original size
    return;
  }

  // Commit the resize
  eraseTable(t);
  t.cMin = newCMin;
  t.cMax = newCMax;
  stampTable(t);
  positionEl(t);
});

