// Set handle CSS classes based on current couch orientation.
// "h" → left/right handles;  "v" → top/bottom handles.
function applyHandleClasses(t) {
  t.handleA.className = "couch-handle " + (t.orientation === "h" ? "handle-left"  : "handle-top");
  t.handleB.className = "couch-handle " + (t.orientation === "h" ? "handle-right" : "handle-bot");
}

// ── Couch rotation ───────────────────────────────────────────────────────
// R key: if in couch mode, toggle ghostOrientation.
//        if a couch is selected, rotate it in-place (snap back if no room).
function handleRotate() {
  if (couchMode) {
    // Flip the ghost orientation for the next placement
    ghostOrientation = ghostOrientation === "h" ? "v" : "h";
    // Refresh ghost at last known cursor position (re-fire on next mousemove is fine)
    couchGhostEl.style.display = "none";
    return;
  }
  if (selectedTable && selectedTable.type === "couch") {
    rotateCouch(selectedTable);
  }
}

function rotateCouch(t) {
  const newOrientation = t.orientation === "h" ? "v" : "h";
  // Pivot around top-left corner: swap (rMax-rMin) ↔ (cMax-cMin)
  const height = t.rMax - t.rMin; // current row-span minus 1
  const width  = t.cMax - t.cMin; // current col-span minus 1
  const newRMax = t.rMin + width;
  const newCMax = t.cMin + height;
  // Clamp to board
  const rMax = Math.min(newRMax, SIZE - 1);
  const cMax = Math.min(newCMax, SIZE - 1);
  const rMin = t.rMin;
  const cMin = t.cMin;
  // Check for conflicts (ignoring self)
  if (hasConflictForCouch(rMin, cMin, rMax, cMax, t.id)) return;
  eraseTable(t);
  t.rMax = rMax;
  t.cMax = cMax;
  t.orientation = newOrientation;
  stampTable(t);
  positionEl(t);
  applyHandleClasses(t);
}

