/* Ghost preview while dragging a table */
.table-ghost {
  position: absolute;
  border: 2px dashed rgba(255,255,255,0.6);
  border-radius: 2px;
  pointer-events: none;
  z-index: 9;
  background: rgba(255,255,255,0.12);
}

/* ── L-shape sofa ──────────────────────────────────────────────────────── */
.lsofa-rect {
  position: absolute;
  pointer-events: all;
  cursor: grab;
  transition: filter 0.1s;
}
/* The visible L shape is drawn as an SVG background */
.lsofa-rect:hover  { filter: brightness(1.15); }
.lsofa-rect.table-selected { filter: brightness(1.2) drop-shadow(0 0 4px #fff); }
.lsofa-rect.moving { cursor: grabbing; opacity: 0.75; z-index: 10; }

/* Resize handles — shown only when selected */
.lsofa-handle {
  position: absolute;
  width: 8px;
  height: 16px;
  background: #b86fc4;
  border: 1px solid #fff6;
  border-radius: 3px;
  pointer-events: all;
  z-index: 11;
  opacity: 0;
  transition: opacity 0.15s;
}
.table-selected .lsofa-handle { opacity: 1; }

/* L-sofa placement ghost */
#lsofa-ghost {
  position: absolute;
  pointer-events: none;
  z-index: 9;
  display: none;
}

