// ── L-shape sofa ─────────────────────────────────────────────────────────
// An L-sofa is defined by:
//   corner:  (r, c) — the corner cell (inner corner of the L)
//   lenA:    length of the horizontal arm (≥ 2)
//   lenB:    length of the vertical arm   (≥ 2)
//   variant: "se" | "sw" | "ne" | "nw"
//            describes which direction each arm extends FROM the corner:
//            first letter = vertical direction of vert arm
//            second letter = horizontal direction of horiz arm
//
//  "se": H arm → right, V arm → down   (corner = top-left  of bounding box)
//  "sw": H arm → left,  V arm → down   (corner = top-right)
//  "ne": H arm → right, V arm → up     (corner = bottom-left)
//  "nw": H arm → left,  V arm → up     (corner = bottom-right)
//
// The two arms share the corner cell; total cells = lenA + lenB - 1.
//
// Stored on piece:  { ..., type:"lsofa", cornerR, cornerC, lenA, lenB, variant }
// rMin/rMax/cMin/cMax = bounding box (used by drag logic).

const LSOFA_COLORS = [
  "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
  "#3cc09a","#c0b03c","#803cc0","#c05a3c",
];
const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];

/** Return the bounding box for an L-sofa piece/params. */
function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
  switch (variant) {
    case "se": return { rMin: cornerR,        cMin: cornerC,        rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
    case "sw": return { rMin: cornerR,        cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
    case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,    rMax: cornerR,            cMax: cornerC + lenA - 1 };
    case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,   cMax: cornerC };
  }
}

/** Return array of {r,c} cells occupied by an L-sofa. */
function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
  const cells = [];
  const seen  = new Set();
  function add(r, c) {
    const k = r + "," + c;
    if (!seen.has(k)) { seen.add(k); cells.push({r,c}); }
  }
  // Horizontal arm
  for (let i = 0; i < lenA; i++) {
    const c = (variant === "sw" || variant === "nw") ? cornerC - i : cornerC + i;
    add(cornerR, c);
  }
  // Vertical arm
  for (let i = 0; i < lenB; i++) {
    const r = (variant === "ne" || variant === "nw") ? cornerR - i : cornerR + i;
    add(r, cornerC);
  }
  return cells;
}

/** Clamp corner so the whole L fits on the board. Returns clamped {cornerR,cornerC}. */
function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
  const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
  let dr = 0, dc = 0;
  if (bb.rMin < 0)       dr = -bb.rMin;
  if (bb.rMax >= SIZE)   dr = SIZE - 1 - bb.rMax;
  if (bb.cMin < 0)       dc = -bb.cMin;
  if (bb.cMax >= SIZE)   dc = SIZE - 1 - bb.cMax;
  return { cornerR: cornerR + dr, cornerC: cornerC + dc };
}

/** Conflict check for an L-sofa given its cells. ignoreId to skip self. */
function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId = null) {
  for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant)) {
    for (const tid of tableGrid[r][c]) {
      if (tid !== ignoreId) return true;
    }
  }
  return false;
}

/** Stamp an L-sofa's cells into tableGrid and colour the board cells. */
function stampLsofa(t) {
  for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
    cells[r][c].classList.remove("selected","light","dark","preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

/** Erase an L-sofa's cells from tableGrid, restore board cells. */
function eraseLsofa(t) {
  for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) {
      resetCell(r, c);
    } else {
      const topId = tableGrid[r][c][tableGrid[r][c].length - 1];
      const top   = tables.find(p => p.id === topId);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity = "0.85"; }
    }
  }
}

/**
 * Draw the L shape on a canvas element.
 * The canvas covers the bounding box.
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} W  canvas width in px
 * @param {number} H  canvas height in px
 * @param {number} lenA  horizontal arm length in cells
 * @param {number} lenB  vertical arm length in cells
 * @param {string} variant
 * @param {string} fillColor   e.g. "rgba(192,112,60,0.55)"
 * @param {string} strokeColor e.g. "#c0703c"
 * @param {boolean} conflict
 */
function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
  const armW = lenA * CELL;   // horizontal arm pixel width  = full width of bbox
  const armH = lenB * CELL;   // vertical   arm pixel height = full height of bbox
  // The L occupies: a horizontal strip (1 cell tall) + a vertical strip (1 cell wide)
  // sharing the corner cell.
  ctx.clearRect(0, 0, W, H);
  ctx.beginPath();
  // Build polygon points depending on variant.
  // Bbox = W × H.  All coords in px relative to bbox top-left.
  switch (variant) {
    case "se":
      // Corner = top-left. H arm: top row. V arm: left col.
      ctx.moveTo(0,    0);
      ctx.lineTo(armW, 0);
      ctx.lineTo(armW, CELL);
      ctx.lineTo(CELL, CELL);
      ctx.lineTo(CELL, armH);
      ctx.lineTo(0,    armH);
      ctx.closePath();
      break;
    case "sw":
      // Corner = top-right. H arm: top row (←). V arm: right col (↓).
      ctx.moveTo(W,        0);
      ctx.lineTo(0,        0);
      ctx.lineTo(0,        CELL);
      ctx.lineTo(W - CELL, CELL);
      ctx.lineTo(W - CELL, armH);
      ctx.lineTo(W,        armH);
      ctx.closePath();
      break;
    case "ne":
      // Corner = bottom-left. H arm: bottom row (→). V arm: left col (↑).
      ctx.moveTo(0,    H);
      ctx.lineTo(armW, H);
      ctx.lineTo(armW, H - CELL);
      ctx.lineTo(CELL, H - CELL);
      ctx.lineTo(CELL, 0);
      ctx.lineTo(0,    0);
      ctx.closePath();
      break;
    case "nw":
      // Corner = bottom-right. H arm: bottom row (←). V arm: right col (↑).
      ctx.moveTo(W,        H);
      ctx.lineTo(0,        H);
      ctx.lineTo(0,        H - CELL);
      ctx.lineTo(W - CELL, H - CELL);
      ctx.lineTo(W - CELL, 0);
      ctx.lineTo(W,        0);
      ctx.closePath();
      break;
  }
  if (conflict) {
    ctx.fillStyle   = "rgba(255,60,60,0.35)";
    ctx.strokeStyle = "rgba(255,80,80,0.9)";
  } else {
    ctx.fillStyle   = fillColor;
    ctx.strokeStyle = strokeColor;
  }
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.stroke();
}

/** Position and redraw the SVG/canvas overlay element for a placed L-sofa. */
function renderLsofaEl(t) {
  const bb = lsofaBBox(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant);
  t.rMin = bb.rMin; t.rMax = bb.rMax; t.cMin = bb.cMin; t.cMax = bb.cMax;
  const W = (bb.cMax - bb.cMin + 1) * CELL;
  const H = (bb.rMax - bb.rMin + 1) * CELL;
  t.el.style.left   = (bb.cMin * CELL) + "px";
  t.el.style.top    = (bb.rMin * CELL) + "px";
  t.el.style.width  = W + "px";
  t.el.style.height = H + "px";
  t.canvas.width  = W;
  t.canvas.height = H;
  const ctx = t.canvas.getContext("2d");
  drawLshape(ctx, W, H, t.lenA, t.lenB, t.variant, t.color + "88", t.color, false);
  // Position resize handles
  positionLsofaHandles(t);
}

/** Place the two resize handles (arm-A tip and arm-B tip). */
function positionLsofaHandles(t) {
  const bb = lsofaBBox(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant);
  const W = (bb.cMax - bb.cMin + 1) * CELL;
  const H = (bb.rMax - bb.rMin + 1) * CELL;
  // handleA controls lenA (H arm tip), handleB controls lenB (V arm tip).
  // Tip of H arm (opposite side from corner, along horizontal):
  switch (t.variant) {
    case "se":
      // H arm tip = right edge, middle of H arm row
      t.handleA.style.right  = "-5px"; t.handleA.style.left = "";
      t.handleA.style.top    = Math.round(CELL/2 - 8) + "px"; t.handleA.style.bottom = "";
      t.handleA.style.width  = "8px";  t.handleA.style.height = "16px";
      t.handleA.style.cursor = "ew-resize";
      // V arm tip = bottom edge, middle of V arm col
      t.handleB.style.bottom = "-5px"; t.handleB.style.top = "";
      t.handleB.style.left   = Math.round(CELL/2 - 8) + "px"; t.handleB.style.right = "";
      t.handleB.style.width  = "16px"; t.handleB.style.height = "8px";
      t.handleB.style.cursor = "ns-resize";
      break;
    case "sw":
      // H arm tip = left edge
      t.handleA.style.left   = "-5px"; t.handleA.style.right = "";
      t.handleA.style.top    = Math.round(CELL/2 - 8) + "px"; t.handleA.style.bottom = "";
      t.handleA.style.width  = "8px";  t.handleA.style.height = "16px";
      t.handleA.style.cursor = "ew-resize";
      // V arm tip = bottom edge, but arm is on right col
      t.handleB.style.bottom = "-5px"; t.handleB.style.top = "";
      t.handleB.style.right  = Math.round(CELL/2 - 8) + "px"; t.handleB.style.left = "";
      t.handleB.style.width  = "16px"; t.handleB.style.height = "8px";
      t.handleB.style.cursor = "ns-resize";
      break;
    case "ne":
      // H arm tip = right edge
      t.handleA.style.right  = "-5px"; t.handleA.style.left = "";
      t.handleA.style.bottom = Math.round(CELL/2 - 8) + "px"; t.handleA.style.top = "";
      t.handleA.style.width  = "8px";  t.handleA.style.height = "16px";
      t.handleA.style.cursor = "ew-resize";
      // V arm tip = top edge
      t.handleB.style.top    = "-5px"; t.handleB.style.bottom = "";
      t.handleB.style.left   = Math.round(CELL/2 - 8) + "px"; t.handleB.style.right = "";
      t.handleB.style.width  = "16px"; t.handleB.style.height = "8px";
      t.handleB.style.cursor = "ns-resize";
      break;
    case "nw":
      // H arm tip = left edge
      t.handleA.style.left   = "-5px"; t.handleA.style.right = "";
      t.handleA.style.bottom = Math.round(CELL/2 - 8) + "px"; t.handleA.style.top = "";
      t.handleA.style.width  = "8px";  t.handleA.style.height = "16px";
      t.handleA.style.cursor = "ew-resize";
      // V arm tip = top edge, arm on right col
      t.handleB.style.top    = "-5px"; t.handleB.style.bottom = "";
      t.handleB.style.right  = Math.round(CELL/2 - 8) + "px"; t.handleB.style.left = "";
      t.handleB.style.width  = "16px"; t.handleB.style.height = "8px";
      t.handleB.style.cursor = "ns-resize";
      break;
  }
}

// ── L-sofa mode enter/exit ────────────────────────────────────────────────
function toggleLsofaMode() {
  if (lsofaMode) exitLsofaMode();
  else enterLsofaMode();
}
function enterLsofaMode() {
  exitCouchMode();
  exitChairMode();
  lsofaMode = true;
  btnLsofa.style.borderColor = "#e07b3c";
  btnLsofa.style.background  = "#6a2a0a";
  board.style.cursor = "none";
}
function exitLsofaMode() {
  if (!lsofaMode) return;
  lsofaMode = false;
  lsofaVariant = "se";
  lsofaGhostLenA = 3;
  lsofaGhostLenB = 3;
  btnLsofa.style.borderColor = "";
  btnLsofa.style.background  = "";
  board.style.cursor = "crosshair";
  lsofaGhostEl.style.display = "none";
}
btnLsofa.addEventListener("click", toggleLsofaMode);

// ── L-sofa ghost ─────────────────────────────────────────────────────────
function updateLsofaGhost(row, col) {
  const { cornerR, cornerC } = clampLsofaCorner(row, col, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant);
  const bb = lsofaBBox(cornerR, cornerC, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant);
  const W  = (bb.cMax - bb.cMin + 1) * CELL;
  const H  = (bb.rMax - bb.rMin + 1) * CELL;
  lsofaGhostEl.style.left    = (bb.cMin * CELL) + "px";
  lsofaGhostEl.style.top     = (bb.rMin * CELL) + "px";
  lsofaGhostEl.style.width   = W + "px";
  lsofaGhostEl.style.height  = H + "px";
  lsofaGhostEl.style.display = "block";
  lsofaGhostCanvas.width  = W;
  lsofaGhostCanvas.height = H;
  const conflict = hasConflictL(cornerR, cornerC, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant);
  drawLshape(lsofaGhostCanvas.getContext("2d"), W, H,
             lsofaGhostLenA, lsofaGhostLenB, lsofaVariant,
             "rgba(224,123,60,0.30)", "#e07b3c", conflict);
}

board.addEventListener("mousemove", (e) => {
  if (!lsofaMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  updateLsofaGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});
board.addEventListener("mouseleave", () => {
  if (lsofaMode) lsofaGhostEl.style.display = "none";
});
board.addEventListener("click", (e) => {
  if (!lsofaMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  placeLsofa(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

// ── Place L-sofa ─────────────────────────────────────────────────────────
function placeLsofa(row, col) {
  const { cornerR, cornerC } = clampLsofaCorner(row, col, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant);
  if (hasConflictL(cornerR, cornerC, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant)) return;

  const color = LSOFA_COLORS[lsofaCount % LSOFA_COLORS.length];
  const id    = tableCount++;
  lsofaCount++;
  const label = `L-Sofa ${lsofaCount}`;

  const el = document.createElement("div");
  el.className = "lsofa-rect";
  el.title = label;

  const canvas = document.createElement("canvas");
  canvas.style.display = "block";
  el.appendChild(canvas);

  const handleA = document.createElement("div");
  const handleB = document.createElement("div");
  handleA.className = "lsofa-handle";
  handleB.className = "lsofa-handle";
  el.appendChild(handleA);
  el.appendChild(handleB);

  const bb = lsofaBBox(cornerR, cornerC, lsofaGhostLenA, lsofaGhostLenB, lsofaVariant);
  const t = {
    id, color, label, el, canvas, handleA, handleB,
    type: "lsofa",
    cornerR, cornerC,
    lenA: lsofaGhostLenA, lenB: lsofaGhostLenB,
    variant: lsofaVariant,
    rMin: bb.rMin, rMax: bb.rMax, cMin: bb.cMin, cMax: bb.cMax,
  };

  tables.push(t);
  renderLsofaEl(t);
  stampLsofa(t);
  overlay.appendChild(el);

  el.addEventListener("mousedown", (e) => {
    if (e.target.classList.contains("lsofa-handle")) return;
    onTableMouseDown(e, t);
  });
  el.addEventListener("click", (e) => { e.stopPropagation(); selectTable(t); });
  handleA.addEventListener("mousedown", (e) => { e.stopPropagation(); startLsofaResize(e, t, "a"); });
  handleB.addEventListener("mousedown", (e) => { e.stopPropagation(); startLsofaResize(e, t, "b"); });
}

// ── L-sofa rotation ───────────────────────────────────────────────────────
// In lsofa mode, R cycles ghost variant.
// On a selected L-sofa, R rotates it (snap back on conflict).
// handleRotate() already dispatches to this after the existing couch check.
function handleLsofaRotate() {
  if (lsofaMode) {
    const idx = LSOFA_VARIANT_CYCLE.indexOf(lsofaVariant);
    lsofaVariant = LSOFA_VARIANT_CYCLE[(idx + 1) % 4];
    return;
  }
  if (selectedTable && selectedTable.type === "lsofa") {
    const t = selectedTable;
    const idx = LSOFA_VARIANT_CYCLE.indexOf(t.variant);
    const newVariant = LSOFA_VARIANT_CYCLE[(idx + 1) % 4];
    // Corner stays the same; check if new orientation fits
    const { cornerR, cornerC } = clampLsofaCorner(t.cornerR, t.cornerC, t.lenA, t.lenB, newVariant);
    if (hasConflictL(cornerR, cornerC, t.lenA, t.lenB, newVariant, t.id)) return;
    eraseLsofa(t);
    t.variant = newVariant;
    t.cornerR = cornerR; t.cornerC = cornerC;
    stampLsofa(t);
    renderLsofaEl(t);
  }
}

// ── L-sofa resize ─────────────────────────────────────────────────────────
// handleA → lenA (H arm), handleB → lenB (V arm).
let resizingLsofa = null; // { t, arm }

function startLsofaResize(e, t, arm) {
  e.preventDefault();
  resizingLsofa = { t, arm };
  // Show ghost at current position
  const bb = lsofaBBox(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant);
  const W = (bb.cMax - bb.cMin + 1) * CELL;
  const H = (bb.rMax - bb.rMin + 1) * CELL;
  lsofaGhostEl.style.left    = (bb.cMin * CELL) + "px";
  lsofaGhostEl.style.top     = (bb.rMin * CELL) + "px";
  lsofaGhostEl.style.width   = W + "px";
  lsofaGhostEl.style.height  = H + "px";
  lsofaGhostCanvas.width  = W;
  lsofaGhostCanvas.height = H;
  lsofaGhostEl.style.display = "block";
  drawLshape(lsofaGhostCanvas.getContext("2d"), W, H, t.lenA, t.lenB, t.variant,
             "rgba(224,123,60,0.30)", "#e07b3c", false);
}

document.addEventListener("mousemove", (e) => {
  if (!resizingLsofa) return;
  const { t, arm } = resizingLsofa;
  const { row, col } = boardCoords(e);
  let newLenA = t.lenA, newLenB = t.lenB;

  if (arm === "a") {
    // lenA = H arm. The H arm tip col depends on variant.
    switch (t.variant) {
      case "se": case "ne": newLenA = Math.max(2, col - t.cornerC + 1); break;
      case "sw": case "nw": newLenA = Math.max(2, t.cornerC - col + 1); break;
    }
    newLenA = Math.min(newLenA, SIZE); // cap to board
  } else {
    // lenB = V arm. The V arm tip row depends on variant.
    switch (t.variant) {
      case "se": case "sw": newLenB = Math.max(2, row - t.cornerR + 1); break;
      case "ne": case "nw": newLenB = Math.max(2, t.cornerR - row + 1); break;
    }
    newLenB = Math.min(newLenB, SIZE);
  }

  // Clamp corner so L stays on board
  const { cornerR, cornerC } = clampLsofaCorner(t.cornerR, t.cornerC, newLenA, newLenB, t.variant);
  const bb  = lsofaBBox(cornerR, cornerC, newLenA, newLenB, t.variant);
  const W   = (bb.cMax - bb.cMin + 1) * CELL;
  const H   = (bb.rMax - bb.rMin + 1) * CELL;
  const conflict = hasConflictL(cornerR, cornerC, newLenA, newLenB, t.variant, t.id);

  lsofaGhostEl.style.left    = (bb.cMin * CELL) + "px";
  lsofaGhostEl.style.top     = (bb.rMin * CELL) + "px";
  lsofaGhostEl.style.width   = W + "px";
  lsofaGhostEl.style.height  = H + "px";
  lsofaGhostCanvas.width  = W;
  lsofaGhostCanvas.height = H;
  drawLshape(lsofaGhostCanvas.getContext("2d"), W, H, newLenA, newLenB, t.variant,
             "rgba(224,123,60,0.30)", "#e07b3c", conflict);
  // Store tentative dims for commit on mouseup
  resizingLsofa.newLenA = newLenA;
  resizingLsofa.newLenB = newLenB;
  resizingLsofa.newCornerR = cornerR;
  resizingLsofa.newCornerC = cornerC;
  resizingLsofa.conflict   = conflict;
});

document.addEventListener("mouseup", (e) => {
  if (!resizingLsofa) return;
  const { t, newLenA, newLenB, newCornerR, newCornerC, conflict } = resizingLsofa;
  resizingLsofa = null;
  lsofaGhostEl.style.display = "none";
  if (!conflict && newLenA !== undefined) {
    eraseLsofa(t);
    t.lenA = newLenA; t.lenB = newLenB;
    t.cornerR = newCornerR; t.cornerC = newCornerC;
    stampLsofa(t);
    renderLsofaEl(t);
  }
});

// ── L-shape sofa ─────────────────────────────────────────────────────────
// An L-sofa is defined by:
//   corner:  (cornerR, cornerC) — the inner corner cell
//   lenA:    horizontal arm length (≥ 2)
//   lenB:    vertical arm length   (≥ 2)
//   variant: "se" | "sw" | "ne" | "nw"
//
//  "se": H arm → right, V arm → down   (corner = top-left  of bbox)
//  "sw": H arm → left,  V arm → down   (corner = top-right)
//  "ne": H arm → right, V arm → up     (corner = bottom-left)
//  "nw": H arm → left,  V arm → up     (corner = bottom-right)

const LSOFA_COLORS = [
  "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
  "#3cc09a","#c0b03c","#803cc0","#c05a3c",
];
const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];

function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
  switch (variant) {
    case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
    case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
    case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
    case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
  }
}

function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
  const out = []; const seen = new Set();
  const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
  for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
  for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
  return out;
}

function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
  const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
  let dr=0, dc=0;
  if (bb.rMin < 0)     dr = -bb.rMin;
  if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
  if (bb.cMin < 0)     dc = -bb.cMin;
  if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
  return { cornerR: cornerR+dr, cornerC: cornerC+dc };
}

function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId=null) {
  for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant))
    for (const tid of tableGrid[r][c]) if (tid !== ignoreId) return true;
  return false;
}

function stampLsofa(t) {
  for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
    cells[r][c].classList.remove("selected","light","dark","preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

function eraseLsofa(t) {
  for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) { resetCell(r,c); }
    else {
      const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
    }
  }
}

