/** Draw the L polygon onto a canvas context. */
function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
  ctx.clearRect(0, 0, W, H);
  ctx.beginPath();
  switch (variant) {
    case "se":
      ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
      ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
      ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
      break;
    case "sw":
      ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
      ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
      ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
      break;
    case "ne":
      ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
      ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
      ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
      break;
    case "nw":
      ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
      ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
