function toggleLsofaMode() { if (lsofaMode) exitLsofaMode(); else enterLsofaMode(); }
function enterLsofaMode() {
  exitCouchMode(); exitChairMode();
  lsofaMode = true;
  btnLsofa.style.borderColor = "#e07b3c";
  btnLsofa.style.background  = "#6a2a0a";
  board.style.cursor = "none";
}
function exitLsofaMode() {
  if (!lsofaMode) return;
  lsofaMode = false;
  lsofaVariant = "se"; lsofaGhostLenA = 3; lsofaGhostLenB = 3;
  btnLsofa.style.borderColor = ""; btnLsofa.style.background = "";
  board.style.cursor = "crosshair";
  lsofaGhostEl.style.display = "none";
}
btnLsofa.addEventListener("click", toggleLsofaMode);

// ── L-sofa ghost ──────────────────────────────────────────────────────────
function updateLsofaGhost(row, col) {
  const {cornerR,cornerC}=clampLsofaCorner(row,col,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
  const bb=lsofaBBox(cornerR,cornerC,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
  const W=(bb.cMax-bb.cMin+1)*CELL, H=(bb.rMax-bb.rMin+1)*CELL;
  lsofaGhostEl.style.left=(bb.cMin*CELL)+"px"; lsofaGhostEl.style.top=(bb.rMin*CELL)+"px";
  lsofaGhostEl.style.width=W+"px"; lsofaGhostEl.style.height=H+"px";
  lsofaGhostEl.style.display="block";
  lsofaGhostCanvas.width=W; lsofaGhostCanvas.height=H;
  const conflict=hasConflictL(cornerR,cornerC,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
  drawLshape(lsofaGhostCanvas.getContext("2d"),W,H,
             lsofaGhostLenA,lsofaGhostLenB,lsofaVariant,
             "rgba(224,123,60,0.30)","#e07b3c",conflict);
}
board.addEventListener("mousemove", (e) => {
  if (!lsofaMode) return;
  const cell=e.target.closest(".cell"); if(!cell) return;
  updateLsofaGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});
board.addEventListener("mouseleave", () => { if(lsofaMode) lsofaGhostEl.style.display="none"; });
board.addEventListener("click", (e) => {
  if (!lsofaMode) return;
  const cell=e.target.closest(".cell"); if(!cell) return;
  placeLsofa(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

// ── Place L-sofa ──────────────────────────────────────────────────────────
function placeLsofa(row, col) {
  const {cornerR,cornerC}=clampLsofaCorner(row,col,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
  if (hasConflictL(cornerR,cornerC,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant)) return;
  const color=LSOFA_COLORS[lsofaCount%LSOFA_COLORS.length];
  const id=tableCount++; lsofaCount++;
  const label=`L-Sofa ${lsofaCount}`;
  const el=document.createElement("div"); el.className="lsofa-rect"; el.title=label;
  const canvas=document.createElement("canvas"); canvas.style.display="block"; el.appendChild(canvas);
  const handleA=document.createElement("div"); handleA.className="lsofa-handle"; el.appendChild(handleA);
  const handleB=document.createElement("div"); handleB.className="lsofa-handle"; el.appendChild(handleB);
  const bb=lsofaBBox(cornerR,cornerC,lsofaGhostLenA,lsofaGhostLenB,lsofaVariant);
  const t={id,color,label,el,canvas,handleA,handleB,type:"lsofa",
           cornerR,cornerC,lenA:lsofaGhostLenA,lenB:lsofaGhostLenB,variant:lsofaVariant,
           rMin:bb.rMin,rMax:bb.rMax,cMin:bb.cMin,cMax:bb.cMax};
  tables.push(t); renderLsofaEl(t); stampLsofa(t); overlay.appendChild(el);
  el.addEventListener("mousedown",(e)=>{ if(e.target.classList.contains("lsofa-handle")) return; onTableMouseDown(e,t); });
  el.addEventListener("click",(e)=>{ e.stopPropagation(); selectTable(t); });
  handleA.addEventListener("mousedown",(e)=>{ e.stopPropagation(); startLsofaResize(e,t,"a"); });
  handleB.addEventListener("mousedown",(e)=>{ e.stopPropagation(); startLsofaResize(e,t,"b"); });
}

// ── L-sofa rotation ───────────────────────────────────────────────────────
function handleLsofaRotate() {
  if (lsofaMode) {
    const idx=LSOFA_VARIANT_CYCLE.indexOf(lsofaVariant);
    lsofaVariant=LSOFA_VARIANT_CYCLE[(idx+1)%4]; return;
  }
  if (selectedTable && selectedTable.type==="lsofa") {
    const t=selectedTable;
    const newVar=LSOFA_VARIANT_CYCLE[(LSOFA_VARIANT_CYCLE.indexOf(t.variant)+1)%4];
    const {cornerR,cornerC}=clampLsofaCorner(t.cornerR,t.cornerC,t.lenA,t.lenB,newVar);
    if (hasConflictL(cornerR,cornerC,t.lenA,t.lenB,newVar,t.id)) return;
    eraseLsofa(t); t.variant=newVar; t.cornerR=cornerR; t.cornerC=cornerC;
    stampLsofa(t); renderLsofaEl(t);
  }
}

