  lsofaGhostEl.style.left=(bb.cMin*CELL)+"px"; lsofaGhostEl.style.top=(bb.rMin*CELL)+"px";
  lsofaGhostEl.style.width=W+"px"; lsofaGhostEl.style.height=H+"px";
