  const conflict=hasConflictL(cornerR,cornerC,newLenA,newLenB,t.variant,t.id);
  lsofaGhostEl.style.left=(bb.cMin*CELL)+"px"; lsofaGhostEl.style.top=(bb.rMin*CELL)+"px";
  lsofaGhostEl.style.width=W+"px"; lsofaGhostEl.style.height=H+"px";
  lsofaGhostCanvas.width=W; lsofaGhostCanvas.height=H;
  drawLshape(lsofaGhostCanvas.getContext("2d"),W,H,newLenA,newLenB,t.variant,
             "rgba(224,123,60,0.30)","#e07b3c",conflict);
  Object.assign(resizingLsofa,{newLenA,newLenB,newCornerR:cornerR,newCornerC:cornerC,conflict});
});
document.addEventListener("mouseup", (e) => {
  if (!resizingLsofa) return;
  const {t,newLenA,newLenB,newCornerR,newCornerC,conflict}=resizingLsofa;
  resizingLsofa=null; lsofaGhostEl.style.display="none";
  if (!conflict && newLenA!==undefined) {
    eraseLsofa(t); t.lenA=newLenA; t.lenB=newLenB; t.cornerR=newCornerR; t.cornerC=newCornerC;
    stampLsofa(t); renderLsofaEl(t);
  }
});

