let resizingCouch = null; // { t, side }

// L-sofa resize mousemove / mouseup handlers
document.addEventListener("mousemove", (e) => {
  if (!resizingLsofa) return;
  const {t,arm}=resizingLsofa, {row,col}=boardCoords(e);
  let newLenA=t.lenA, newLenB=t.lenB;
  if (arm==="a") {
    if (t.variant==="se"||t.variant==="ne") newLenA=Math.max(2,col-t.cornerC+1);
    else                                     newLenA=Math.max(2,t.cornerC-col+1);
    newLenA=Math.min(newLenA,SIZE);
  } else {
    if (t.variant==="se"||t.variant==="sw") newLenB=Math.max(2,row-t.cornerR+1);
    else                                     newLenB=Math.max(2,t.cornerR-row+1);
    newLenB=Math.min(newLenB,SIZE);
  }
  const {cornerR,cornerC}=clampLsofaCorner(t.cornerR,t.cornerC,newLenA,newLenB,t.variant);
  const bb=lsofaBBox(cornerR,cornerC,newLenA,newLenB,t.variant);
  const W=(bb.cMax-bb.cMin+1)*CELL, H=(bb.rMax-bb.rMin+1)*CELL;
  const conflict=hasConflictL(cornerR,cornerC,newLenA,newLenB,t.variant,t.id);
  lsofaGhostEl.style.left=(bb.cMin*CELL)+"px"; lsofaGhostEl.style.top=(bb.rMin*CELL)+"px";
  lsofaGhostEl.style.width=W+"px"; lsofaGhostEl.style.height=H+"px";
  lsofaGhostCanvas.width=W; lsofaGhostCanvas.height=H;
  drawLshape(lsofaGhostCanvas.getContext("2d"),W,H,newLenA,newLenB,t.variant,"rgba(224,123,60,0.30)","#e07b3c",conflict);
  Object.assign(resizingLsofa,{newLenA,newLenB,newCornerR:cornerR,newCornerC:cornerC,conflict});
});
document.addEventListener("mouseup", (e) => {
  if (!resizingLsofa) return;
  const {t,newLenA,newLenB,newCornerR,newCornerC,conflict}=resizingLsofa;
  resizingLsofa=null; lsofaGhostEl.style.display="none";
  if (!conflict && newLenA!==undefined) {
    eraseLsofa(t); t.lenA=newLenA; t.lenB=newLenB; t.cornerR=newCornerR; t.cornerC=newCornerC;
    stampLsofa(t); renderLsofaEl(t);
  }
});

