document.addEventListener("mousemove", (e) => {
  if (!movingTable) return;
  if (resizingCouch) return;
  if (resizingLsofa) return;
  const {row,col} = boardCoords(e);
  const h = movingTable.rMax - movingTable.rMin;
  const w = movingTable.cMax - movingTable.cMin;
  const s = clampTable(row-moveOffsetRow, col-moveOffsetCol,
                       row-moveOffsetRow+h, col-moveOffsetCol+w);
  ghost.style.left           = (s.cMin*CELL)+"px";
  ghost.style.top            = (s.rMin*CELL)+"px";
  movingTable.el.style.left  = (s.cMin*CELL)+"px";
  movingTable.el.style.top   = (s.rMin*CELL)+"px";
  // Tint ghost red if drop zone conflicts with another table (or invalid for chair)
  let conflict;
  if (movingTable.type === "lsofa") {
    const newCornerR = s.rMin + (movingTable.cornerR - movingTable.rMin);
    const newCornerC = s.cMin + (movingTable.cornerC - movingTable.cMin);
    conflict = hasConflictL(newCornerR, newCornerC, movingTable.lenA, movingTable.lenB, movingTable.variant, movingTable.id);
  } else {
    conflict = (movingTable.type === "chair"
                ? hasConflictForChair(s.rMin, s.cMin, movingTable.id)
                : movingTable.type === "couch"
                ? hasConflictForCouch(s.rMin, s.cMin, s.rMax, s.cMax, movingTable.id)
                : hasConflict(s.rMin, s.cMin, s.rMax, s.cMax, movingTable.id))
            || (movingTable.type === "chair" && !isAdjacentToTable(s.rMin, s.cMin));
  }
  ghost.style.borderColor      = conflict ? "rgba(255,80,80,0.9)" : "rgba(255,255,255,0.6)";
  ghost.style.backgroundColor  = conflict ? "rgba(255,60,60,0.25)" : "rgba(255,255,255,0.12)";
  // Highlight the specific conflicting cells red
  if (conflict) applyDragConflict(s.rMin,s.cMin,s.rMax,s.cMax, movingTable.id);
  else clearDragConflict();
});

