document.addEventListener("mouseup", (e) => {
  if (!movingTable) return;
  if (resizingCouch) return;
  if (resizingLsofa) return;
  const t = movingTable;
  const {row,col} = boardCoords(e);
  const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
  const s = clampTable(row-moveOffsetRow, col-moveOffsetCol,
                       row-moveOffsetRow+h, col-moveOffsetCol+w);

  let conflict;
  if (t.type === "lsofa") {
    const newCornerR = s.rMin + (t.cornerR - t.rMin);
    const newCornerC = s.cMin + (t.cornerC - t.cMin);
    conflict = hasConflictL(newCornerR, newCornerC, t.lenA, t.lenB, t.variant, t.id);
  } else {
    conflict = (t.type === "chair"
                ? hasConflictForChair(s.rMin, s.cMin, t.id)
                : t.type === "couch"
                ? hasConflictForCouch(s.rMin, s.cMin, s.rMax, s.cMax, t.id)
                : hasConflict(s.rMin, s.cMin, s.rMax, s.cMax, t.id))
            || (t.type === "chair" && !isAdjacentToTable(s.rMin, s.cMin));
  }

  clearDragConflict();
  if (t.type === "lsofa") {
    eraseLsofa(t);
    if (!conflict) {
      t.cornerR = s.rMin + (t.cornerR - t.rMin);
      t.cornerC = s.cMin + (t.cornerC - t.cMin);
    }
    stampLsofa(t);
    renderLsofaEl(t);
  } else {
    eraseTable(t);
    if (!conflict) { t.rMin=s.rMin; t.cMin=s.cMin; t.rMax=s.rMax; t.cMax=s.cMax; }
    // If conflict, t's coords are unchanged → snap back to original position
    stampTable(t);
    positionEl(t);
  }
  t.el.classList.remove("moving");
  overlay.removeChild(ghost);
  ghost = null; movingTable = null;
});

