/* Chair furniture — 1×1 circle */
.chair-rect {
  position: absolute;
  border: 2px solid rgba(0,0,0,0.35);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 7px;
  font-weight: bold;
  color: rgba(0,0,0,0.6);
  overflow: hidden;
  pointer-events: all;
  cursor: grab;
  transition: box-shadow 0.1s;
}
.chair-rect:hover      { box-shadow: 0 0 0 2px #fff8; }
.chair-rect.table-selected { box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgba(255,255,255,0.4); }
.chair-rect.moving     { cursor: grabbing; opacity: 0.75; z-index: 10; box-shadow: 0 4px 16px rgba(0,0,0,0.5); border-style: dashed; }

/* Stack badge — shown on the topmost chair when count > 1 */
.chair-stack-badge {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
  color: #fff;
  text-shadow: 0 0 3px rgba(0,0,0,0.8);
  pointer-events: none;
}
/* Ring that thickens when stacked to hint depth */
.chair-rect.stacked {
  border-width: 3px;
  border-color: rgba(0,0,0,0.6);
  box-shadow: inset 0 0 0 2px rgba(255,255,255,0.25);
}

