input.new_text:
function placeChair(row, col) {
  if (hasConflictForChair(row, col)) return;
  if (!isAdjacentToTable(row, col)) return;

  const id    = tableCount++;
  chairCount++;
  const label = `Ch${chairCount}`;

  const el = document.createElement("div");
  el.className = "chair-rect";
  el.style.backgroundColor = CHAIR_COLOR + "88";
  el.style.borderColor     = CHAIR_COLOR;

  // Badge span — always present, content managed by refreshChairBadge
  const badge = document.createElement("span");
  badge.className = "chair-stack-badge";
  el.appendChild(badge);

  const t = { id, rMin: row, cMin: col, rMax: row, cMax: col, color: CHAIR_COLOR, label, el, badge, type: "chair" };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
  el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });

  refreshChairBadge(row, col);
}

/**
 * Refresh the stack-count badge on the topmost chair at (r, c).
 * – Counts every chair ID in tableGrid[r][c].
 * – On the topmost chair: shows "×N" when N > 1, clears when N === 1.
 * – On all other chairs at the cell: clears their badge (they're hidden underneath).
 * – Adds/removes the `.stacked` class to signal depth visually.
 */
function refreshChairBadge(r, c) {
  const ids = tableGrid[r][c];
  // Collect chairs at this cell in stack order (bottom → top)
  const chairIds = ids.filter(id => {
    const p = tables.find(t => t.id === id);
    return p && p.type === "chair";
  });
  const count = chairIds.length;

  chairIds.forEach((id, idx) => {
    const p = tables.find(t => t.id === id);
    if (!p || !p.badge) return;
    const isTop = (idx === count - 1);
    if (isTop && count > 1) {
      p.badge.textContent = "×" + count;
      p.el.classList.add("stacked");
    } else {
      p.badge.textContent = "";
      p.el.classList.toggle("stacked", count > 1);
    }
  });
}

