function deleteTable(t) {
  if (!t) return;
  // Snapshot chair position before erasing (needed for badge refresh after splice)
  const wasChair = t.type === "chair";
  const chairR = t.rMin, chairC = t.cMin;

  // If this table is currently being edited, cancel the edit first
  if (editingTable === t) {
    editingTable = null;
    delete t._editBackup;
    selection = null;
    clearClass("preview"); clearClass("conflict");
  } else {
    if (t.type === "lsofa") eraseLsofa(t);
    else eraseTable(t);
  }
  // Remove overlay element
  if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
  // Remove from tables array
  const idx = tables.indexOf(t);
  if (idx !== -1) tables.splice(idx, 1);
  // If a stacked chair was deleted, refresh the badge now that t is gone from `tables`
  if (wasChair) refreshChairBadge(chairR, chairC);
  // Deselect
  if (selectedTable === t) selectTable(null);
  renderSelection();
}

